create or replace package body stock_count_api as
  procedure record_count(p_sku in varchar2, p_counted in number) is
    v_reorder_point inventory_levels.reorder_point%TYPE;
    v_current_stock inventory_levels.on_hand%TYPE;
  begin
    -- Get current reorder point and stock level before updating
    select reorder_point, on_hand into v_reorder_point, v_current_stock
    from inventory_levels
    where sku = p_sku;

    -- Update inventory levels
    update inventory_levels set on_hand = p_counted where sku = p_sku;

    -- Check if the new count triggers a reorder request (<= to include the reorder point)
    if p_counted <= v_reorder_point then
      -- To prevent multiple requests when stock falls below reorder point,
      -- we should only create a request if one doesn't already exist for this SKU.
      -- This assumes that a request should only be active/created once until fulfilled.
      if not exists (select 1 from reorder_requests where sku = p_sku) then
        insert into reorder_requests (sku) values (p_sku);
      end if;
    end if;
  end record_count;

  function open_requests(p_sku in varchar2) return number is
    l_count number;
  begin
    select count(*) into l_count from reorder_requests where sku = p_sku;
    return l_count;
  end open_requests;
end stock_count_api;
/
